from dsl import *

LESSON = {
    "id": "l16",
    "label": "16",
    "title": "The articles ang and ng",
    "summary": "When to use ang (the main character) and when to use ng (the other characters), and their plurals",
    "minutes": 25,
    "goals": [
        "Use ang to introduce the subject of a sentence",
        "Use ang in place of ay to stress who did something",
        "Use ng for the receiver of an action, for possession, and for the doer of an -in- verb",
        "Use the plural forms ang mga and ng mga",
    ],
    "sections": [
        S("Two very common words",
          P("**Ang** and **ng** are two of the most commonly used words in Tagalog. You met them in Lesson 8, together with **ni**, as words that show possession."),
          TABLE(["Article", "Its job", "In English"],
                [["[[ang|marker]]", "introduces the **main character** in a sentence", "like the definite article *the*"],
                 ["[[ng|marker]]", "introduces the **other, minor characters**, among other things", "*of*, or the indefinite articles *a* and *an*"]],
                title="Ang and ng"),
          BOX("warn", "A common mix-up", t="Many learners use **ang** where **ng** should be used, and **ng** where **ang** should be used. The rules below help you tell them apart."),
          BOX("tip", "How to say ng", t="Remember from Lesson 8: **ng** is read like **nang**.")),

        S("When to use ang",
          H("a. To introduce the subject"),
          P("**Ang** introduces a **common noun** that is the **subject** of the sentence. Here it is like the English *the*."),
          EXS([("Ang batà ay mabaít at masípag.", "The child is good and diligent.",
                [("Ang", "the", "marker"), ("batà", "child", "noun"), ("ay", "is", "ay"), ("mabaít", "good", "pred"), ("at", "and", "other"), ("masípag", "diligent", "pred")]),
               ("Kumakain ng manggà ang dalaga.", "The young woman is eating a mango.",
                [("Kumakain", "is eating", "pred"), ("ng", "a", "marker"), ("manggà", "mango", "noun"), ("ang", "the", "marker"), ("dalaga", "young woman", "noun")])]),
          P("In the second sentence, **ang dalaga** is the subject even though it comes last, and **ng manggà** is the thing being eaten."),
          H("b. To stress who the doer is"),
          P("Putting **ang** where **ay** would go puts the emphasis on the **identity of the doer**: it marks *who* did it."),
          TABLE(["With ay", "With ang"],
                [["Akó ay sumúlat ng kuwénto. (*I wrote a story.*)", "Akó **ang** sumúlat ng kuwénto. (*I was the one who wrote the story.*)"],
                 ["Ang batà ay maysakít. (*The child is sick.*)", "Ang batà **ang** maysakít. (*The child is the one who is sick.*)"]],
                title="Ay or ang?"),
          EXS([("Akó ang sumúlat ng kuwénto.", "I was the one who wrote the story.",
                [("Akó", "I", "pron"), ("ang", "(the one who)", "marker"), ("sumúlat", "wrote", "pred"), ("ng", "the", "marker"), ("kuwénto", "story", "noun")]),
               ("Ang batà ang maysakít.", "The child is the one who is sick.",
                [("Ang", "the", "marker"), ("batà", "child", "noun"), ("ang", "(the one who is)", "marker"), ("maysakít", "sick", "pred")])]),
          BOX("english", "The one who…", t="English does the same job with *the one who*: *I was **the one who** wrote the story.*")),

        S("When to use ng",
          H("a. The receiver of an action"),
          EXS([("Bumili ng pagkain ang babáe.", "The woman bought food.",
                [("Bumili", "bought", "pred"), ("ng", "(receiver)", "marker"), ("pagkain", "food", "noun"), ("ang", "the", "marker"), ("babáe", "woman", "noun")]),
               ("Si Elena ay nagluto ng manók.", "Elena cooked the chicken.",
                [("Si", "article (one name)", "marker"), ("Elena", "Elena", "noun"), ("ay", "(links)", "ay"), ("nagluto", "cooked", "pred"), ("ng", "(receiver)", "marker"), ("manók", "chicken", "noun")])]),
          H("b. Association or possession"),
          EXS([("Ang iná ng báta ay nagpuntá sa paléngke.", "The child's mother went to the market.",
                [("Ang", "the", "marker"), ("iná", "mother", "noun"), ("ng", "of", "marker"), ("báta", "child", "noun"), ("ay", "(links)", "ay"), ("nagpuntá", "went", "pred"), ("sa", "to", "marker"), ("paléngke", "market", "noun")]),
               ("Ang báhay ng laláki ay bágo.", "The man's house is new.",
                [("Ang", "the", "marker"), ("báhay", "house", "noun"), ("ng", "of", "marker"), ("laláki", "man", "noun"), ("ay", "is", "ay"), ("bágo", "new", "pred")])]),
          H("c. The doer of a passive (-in-) action"),
          P("Look at the **-in-** verbs from Lesson 15: the doer is introduced by **ng**, and the thing acted upon takes **ang**."),
          EXS([("Kináin ng áso ang tinápay.", "The dog ate the bread.",
                [("Kináin", "was eaten", "pred"), ("ng", "by", "marker"), ("áso", "dog", "noun"), ("ang", "the", "marker"), ("tinápay", "bread", "noun")]),
               ("Binilí ng batáng babáe ang aklàt.", "The girl bought the book.",
                [("Binilí", "was bought", "pred"), ("ng", "by", "marker"), ("batáng", "child +ng", "noun"), ("babáe", "woman (female)", "noun"), ("ang", "the", "marker"), ("aklàt", "book", "noun")])]),
          BOX("remember", "Ng has three jobs", items=[
              "the **receiver** of an action: Bumili **ng** pagkain…",
              "**association or possession**: ang báhay **ng** laláki",
              "the **doer** of an -in- action: Kináin **ng** áso…"])),

        S("Plural forms: ang mga and ng mga",
          P("Tagalog follows the **plurality rule** from Lesson 4: plural words must be introduced by the **plural forms** of the articles."),
          TABLE(["Singular", "Plural"],
                [["[[ang|marker]]", "[[ang mga|marker]]"],
                 ["[[ng|marker]]", "[[ng mga|marker]]"]],
                title="The plural articles"),
          EXS([("Ang mga báhay ng magkákapatid na babáe ay malalakì.", "The sisters' houses are big.",
                [("Ang", "the", "marker"), ("mga", "plural marker", "marker"), ("báhay", "houses", "noun"), ("ng", "of", "marker"), ("magkákapatid", "siblings (two or more)", "noun"), ("na", "ligature", "link"), ("babáe", "woman (female)", "noun"), ("ay", "are", "ay"), ("malalakì", "big (plural)", "pred")]),
               ("Bumilí ng mga prutas ang lóla.", "The grandmother bought fruits.",
                [("Bumilí", "bought", "pred"), ("ng", "(receiver)", "marker"), ("mga", "plural marker", "marker"), ("prutas", "fruits", "noun"), ("ang", "the", "marker"), ("lóla", "grandmother", "noun")])]),
          BOX("tip", "Magkákapatid", t="**Magkákapatid** means two or more siblings. With **na babáe** it becomes *sisters*."),
          VOC("words", "Words in this lesson"),
          BOX("remember", "Remember", items=[
              "**Ang** introduces the subject (the main character): *the*.",
              "**Ang** in place of ay stresses who the doer is: Akó ang sumúlat ng kuwénto.",
              "**Ng** introduces the receiver of an action, an owner, or the doer of an -in- verb.",
              "Plural: **ang mga** and **ng mga**."]),
          VOC("more", "More words from this lesson")),
    ],
    "vocab": [
        V("ang-mga-l16", "ang mga", "the (plural of ang)", pos="marker", group="words"),
        V("dalaga-l16", "dalaga", "young woman", group="words", note="Lesson 7 writes dalága (unmarried woman)"),
        V("palengke-l16", "paléngke", "market", say="pa-LENG-ke", group="words"),
        V("magkakapatid-l16", "magkákapatid", "siblings (two or more)", say="mag-KA-ka-pa-tid", group="words", note="Lesson 4 has magkapatíd (siblings)"),
        V("kapitbahay-l16", "kápitbahay", "neighbor", say="KA-pit-ba-hay", group="words"),
        V("maysakit-l16", "maysakít", "sick", say="may-sa-KIT", pos="adj", group="words"),
        V("lola-l16", "lóla", "grandmother", say="LO-la", group="words"),
        V("tinapay-l16", "tinápay", "bread", say="ti-NA-pay", group="words"),
        V("ng-a-m16", "ng", "of; a, an", pos="marker", group="more", note="The book says ng may be translated using the English preposition of or the indefinite articles a and an"),
        V("masipag-m16", "masípag", "diligent", say="ma-SI-pag", pos="adj", group="more", note="Lesson 6 glosses masípag as industrious. From: Ang batà ay mabaít at masípag. = The child is good and diligent."),
        V("kumakain-m16", "kumakain", "is eating", pos="verb", group="more", note="Lessons 5 and 14 print kumákain and kumakáin. From: Kumakain ng manggà ang dalaga. = The young woman is eating a mango."),
        V("sumulat-m16", "sumúlat", "wrote", say="su-MU-lat", pos="verb", group="more", note="Lesson 14 glosses sumúlat as to write. From: Akó ay sumúlat ng kuwénto. = I wrote a story."),
        V("bumili-m16", "bumilí", "bought", say="bu-mi-LI", pos="verb", group="more", note="Lesson 14 glosses bumilí as to buy. Also printed Bumili. From: Bumilí ng mga prutas ang lóla. = The grandmother bought fruits."),
        V("pagkain-m16", "pagkain", "food", pos="noun", group="more", note="Lesson 2 prints pagkáin. From: Bumili ng pagkain ang babáe. = The woman bought food."),
        V("nagluto-m16", "nagluto", "cooked", pos="verb", group="more", note="Lesson 14 prints naglutò. From: Si Elena ay nagluto ng manók. = Elena cooked the chicken."),
        V("nagpunta-m16", "nagpuntá", "went", say="nag-pun-TA", pos="verb", group="more", note="From: Ang iná ng báta ay nagpuntá sa paléngke. = The child's mother went to the market."),
        V("kinain-m16", "kináin", "ate", say="ki-NA-in", pos="verb", group="more", note="From: Kináin ng áso ang tinápay. = The dog ate the bread."),
        V("malalaki-m16", "malalakì", "big (plural)", say="ma-la-LA-kiQ", pos="adj", group="more", note="Lesson 6 prints malalakí. From: Ang mga báhay ng magkákapatid na babáe ay malalakì. = The sisters' houses are big."),
        V("magkakapatid-na-babae-m16", "magkákapatid na babáe", "sisters", say="mag-KA-ka-pa-tid na ba-BA-e", pos="phrase", group="more", note="From: Ang mga báhay ng magkákapatid na babáe ay malalakì. = The sisters' houses are big."),
        V("aklat-m16", "aklàt", "book", say="AK-latQ", pos="noun", group="more", note="Lesson 4 prints aklát. From: Binilí ng batáng babáe ang aklàt. = The girl bought the book."),
        V("prutas-m16", "prutas", "fruits", pos="noun", group="more", note="Lesson 15 prints prútas. From: Bumilí ng mga prutas ang lóla. = The grandmother bought fruits."),
    ],
    "exercises": [
        CH("Which article is like the English \"the\" and introduces the main character?", ["ang", "ng", "ni"], "ang", "Ang introduces the subject."),
        CH("Which article can be translated \"of\", \"a\" or \"an\"?", ["ng", "ang", "si"], "ng", "Ng introduces the other, minor characters."),
        CH("Fill in: Kumakain ng manggà ___ dalaga.", ["ang", "ng", "ng mga"], "ang", "The young woman is the subject: ang dalaga."),
        CH("Fill in: Bumili ___ pagkain ang babáe.", ["ng", "ang", "ang mga"], "ng", "Pagkain (food) receives the action, so it takes ng."),
        CH("Fill in: Kináin ___ áso ang tinápay.", ["ng", "ang", "sa"], "ng", "The doer of an -in- verb takes ng."),
        CH("Fill in: Ang báhay ___ laláki ay bágo.", ["ng", "ang", "ay"], "ng", "Ng shows possession: the man's house."),
        CH("\"Akó ang sumúlat ng kuwénto\" means…", ["I was the one who wrote the story.", "I wrote a story.", "The story was written."], "I was the one who wrote the story.", "Ang in place of ay stresses who the doer is."),
        CH("\"Ang batà ay maysakít\" means…", ["The child is sick.", "The child is the one who is sick.", "The sick child."], "The child is sick.", "With ay it is a plain statement."),
        CH("Which sentence stresses that it is the child who is sick?", ["Ang batà ang maysakít.", "Ang batà ay maysakít."], "Ang batà ang maysakít.", "Ang in place of ay marks the identity of the one who is sick."),
        CH("In \"Kináin ng áso ang tinápay\", what does ng show?", ["the doer of the action", "possession", "the receiver of the action"], "the doer of the action", "With an -in- verb, ng introduces the doer: the dog."),
        CH("In \"Si Elena ay nagluto ng manók\", what does ng show?", ["the receiver of the action", "the doer of the action", "possession"], "the receiver of the action", "The chicken receives the action of cooking."),
        CH("What is the plural of ng?", ["ng mga", "ang mga", "niná"], "ng mga", "Ng becomes ng mga."),
        CH("Fill in: Bumilí ___ prutas ang lóla. (The grandmother bought fruits.)", ["ng mga", "ang mga", "ng"], "ng mga", "Fruits are plural and receive the action: ng mga prutas."),
        CH("Fill in: ___ báhay ___ áking kaibígan ay nasa Quezon City.", ["Ang … ng", "Ng … ang", "Ang … ang"], "Ang … ng", "Ang introduces the subject; ng shows whose house it is."),
        CH("Fill in: ___ pangálan ___ áking asáwa ay John.", ["Ang … ng", "Ng … ng", "Ang … ang"], "Ang … ng", "Ang for the subject, ng for possession."),
        CH("Fill in: Kumákain ___ gúlay ___ malusóg na batà.", ["ng … ang", "ang … ng", "ng … ng"], "ng … ang", "The vegetables receive the action (ng); the healthy child is the subject (ang)."),
        CH("Fill in: ___ pangálan ___ kapatíd ko ay Peter at Mary.", ["Ang mga … ng mga", "Ang … ng", "Ng mga … ang mga"], "Ang mga … ng mga", "Two names, so the plural forms are needed."),
        LI("lóla", ["grandmother", "neighbor", "young woman"], "grandmother", "Lóla = grandmother."),
        LI("kápitbahay", ["neighbor", "siblings", "market"], "neighbor", "Kápitbahay = neighbor."),
        LI("maysakít", ["sick", "story", "bread"], "sick", "Maysakít = sick."),
        BU("The child is good and diligent.", "Ang batà ay mabaít at masípag."),
        BU("The young woman is eating a mango.", "Kumakain ng manggà ang dalaga."),
        BU("I was the one who wrote the story.", "Akó ang sumúlat ng kuwénto.", extra=["ay"]),
        BU("The dog ate the bread.", "Kináin ng áso ang tinápay."),
        BU("The man's house is new.", "Ang báhay ng laláki ay bágo."),
        BU("The grandmother bought fruits.", "Bumilí ng mga prutas ang lóla."),
        MA("Match each word to its meaning.", [("paléngke", "market"), ("kuwénto", "story"), ("tinápay", "bread"), ("magkákapatid", "siblings"), ("dalaga", "young woman")]),
        MA("Match each use to its article.", [("the subject (singular)", "ang"), ("the subject (plural)", "ang mga"), ("an owner (singular)", "ng"), ("an owner (plural)", "ng mga")]),
    ],
    "recap": [
        "Ang introduces the main character (the subject), like the English the.",
        "Ang in place of ay stresses who the doer is: Akó ang sumúlat ng kuwénto.",
        "Ng introduces the receiver of an action, an owner, and the doer of an -in- verb.",
        "Ng can be translated of, a or an.",
        "Plural: ang mga and ng mga.",
    ],
}
